mapper.select:
select g.member_id as memberId, coalesce(u.nickname, u.name) as nickname
  from (


            select c.member_id from club c where c.id = #{guildId} and c.del_flag = 0
            union
            select cm.member_id from club_member cm
             where cm.club_id = #{guildId} and cm.status = 1 and cm.del_flag = 0


            select tm.member_id from play_team_member tm where tm.team_id = #{guildId} and tm.status = 1


  ) g
  left join ums_member u on u.id = g.member_id
 where g.member_id > #{afterMemberId}
 order by g.member_id asc
 limit #{limit}

mapper.update:
update im_channel
   set meta_version = meta_version + 1, update_time = current_timestamp(3)
       , name = #{name}
       , topic = #{topic}
       , visibility = #{visibility}
       , slowmode_sec = #{slowmodeSec}
 where id = #{id} and meta_version = #{expected} and status = 0 and del_flag = 0

mapper.select:
select r.id, r.permissions, r.position
  from im_guild_role r join im_guild_role_member m on m.role_id = r.id
 where r.guild_kind = #{guildKind} and r.guild_id = #{guildId} and r.status = 1 and m.member_id = #{memberId}

select payload_fingerprint as fingerprint, operation, channel_id as channelId, response_json as response
  from im_channel_request_receipt
 where operator_id = #{operatorId} and family = #{family} and request_id = #{requestId}

select id, channel_id as channelId, action, from_status as fromStatus, to_status as toStatus, reason,
       operator_id as operatorId, create_time as createTime
  from im_channel_op_log
 where channel_id = #{channelId}
 and id < #{beforeId}
 order by id desc
 limit #{limit}
